import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

/**
 * OBJ Exporter for Three.js with Blender Z-up conversion
 * Applies -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
 */
class OBJExporter {
  constructor() {
    this.output = '';
    this.vertexIndex = 1; // OBJ format uses 1-based indexing
    this.vertices = [];
    this.faces = [];
  }

  /**
   * Parse and export a Three.js object to OBJ format
   */
  parse(object) {
    // Apply -90 degree X-rotation for Blender Z-up coordinate system
    const rotationMatrix = new THREE.Matrix4();
    rotationMatrix.makeRotationX(-Math.PI / 2);

    this.output = '# OBJ file exported from Three.js\n';
    this.output += '# Converted to Blender Z-up coordinate system\n';
    this.output += `# Generated on ${new Date().toISOString()}\n\n`;

    // Traverse the scene and process all meshes
    object.traverse((node) => {
      if (node.isMesh) {
        this.processMesh(node, rotationMatrix);
      } else if (node.isInstancedMesh) {
        this.processInstancedMesh(node, rotationMatrix);
      }
    });

    // Build the final OBJ output
    let objContent = this.output;

    // Write all vertices
    for (const vertex of this.vertices) {
      objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    objContent += '\n';

    // Write all faces
    for (const face of this.faces) {
      objContent += face;
    }

    return objContent;
  }

  /**
   * Process a regular mesh
   */
  processMesh(mesh, rotationMatrix) {
    const geometry = mesh.geometry;

    if (!geometry.isBufferGeometry) {
      console.warn('Mesh geometry is not BufferGeometry, skipping:', mesh.name);
      return;
    }

    // Clone geometry to avoid modifying the original
    const clonedGeometry = geometry.clone();

    // Get the world matrix for this mesh
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld.clone();

    // Apply rotation matrix to convert to Blender Z-up
    worldMatrix.premultiply(rotationMatrix);

    // Apply transformations to geometry
    clonedGeometry.applyMatrix4(worldMatrix);

    // Ensure geometry has position attribute
    if (!clonedGeometry.attributes.position) {
      console.warn('Geometry has no position attribute, skipping:', mesh.name);
      return;
    }

    this.addGeometry(clonedGeometry, mesh.name || 'mesh');
  }

  /**
   * Process an instanced mesh
   */
  processInstancedMesh(instancedMesh, rotationMatrix) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    if (!geometry.isBufferGeometry) {
      console.warn('InstancedMesh geometry is not BufferGeometry, skipping:', instancedMesh.name);
      return;
    }

    // Get the world matrix for the parent
    instancedMesh.updateMatrixWorld(true);
    const parentWorldMatrix = instancedMesh.matrixWorld.clone();

    // Process each instance
    for (let i = 0; i < count; i++) {
      const instanceMatrix = new THREE.Matrix4();
      instancedMesh.getMatrixAt(i, instanceMatrix);

      // Clone geometry for this instance
      const clonedGeometry = geometry.clone();

      // Combine parent world matrix with instance matrix
      const finalMatrix = parentWorldMatrix.clone();
      finalMatrix.multiply(instanceMatrix);

      // Apply rotation matrix to convert to Blender Z-up
      finalMatrix.premultiply(rotationMatrix);

      // Apply transformations to geometry
      clonedGeometry.applyMatrix4(finalMatrix);

      const instanceName = `${instancedMesh.name || 'instanced_mesh'}_${i}`;
      this.addGeometry(clonedGeometry, instanceName);
    }
  }

  /**
   * Add geometry vertices and faces to the output
   */
  addGeometry(geometry, objectName) {
    this.faces.push(`\n# Object: ${objectName}\n`);
    this.faces.push(`o ${objectName}\n`);

    const positions = geometry.attributes.position;
    const index = geometry.index;

    const startVertexIndex = this.vertexIndex;

    // Add vertices
    for (let i = 0; i < positions.count; i++) {
      const vertex = new THREE.Vector3();
      vertex.fromBufferAttribute(positions, i);
      this.vertices.push(vertex);
    }

    // Add faces
    if (index) {
      // Indexed geometry
      for (let i = 0; i < index.count; i += 3) {
        const a = index.getX(i) + startVertexIndex;
        const b = index.getX(i + 1) + startVertexIndex;
        const c = index.getX(i + 2) + startVertexIndex;
        this.faces.push(`f ${a} ${b} ${c}\n`);
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positions.count; i += 3) {
        const a = i + startVertexIndex;
        const b = i + 1 + startVertexIndex;
        const c = i + 2 + startVertexIndex;
        this.faces.push(`f ${a} ${b} ${c}\n`);
      }
    }

    this.vertexIndex += positions.count;
  }
}

/**
 * Main export function
 */
function exportToOBJ() {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  console.log('Scene created:', scene.name);
  console.log('Converting to OBJ format with Blender Z-up coordinate system...');

  const exporter = new OBJExporter();
  const objData = exporter.parse(scene);

  const outputPath = '/root/output/object.obj';
  const outputDir = path.dirname(outputPath);

  // Ensure output directory exists
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  fs.writeFileSync(outputPath, objData);

  console.log(`Successfully exported to ${outputPath}`);
  console.log(`Total vertices: ${exporter.vertices.length}`);
  console.log(`Total vertex index count: ${exporter.vertexIndex - 1}`);
  console.log('\nNote: Applied -90 degree X-rotation for Blender Z-up coordinate system');
}

// Run the export
exportToOBJ();

